// ********app_star

/*
short int app_star (double jd_tt, CatEntry *star, short int accuracy,
                    double *ra, double *dec)
*/

/*
------------------------------------------------------------------------

   PURPOSE:
      Computes the apparent place of a star at date 'jd_tt', given its
      catalog mean place, proper motion, parallax, and radial velocity.

   REFERENCES:
      Kaplan, G. H. et. al. (1989). Astron. Journ. 97, 1197-1210.
      Explanatory Supplement to the Astronomical Almanac (1992),
         Chapter 3.

   INPUT
   ARGUMENTS:
      jd_tt (double)
         TT Julian date for apparent place.
      *star (struct CatEntry)
         Pointer to catalog entry structure containing catalog data for
         the object in the ICRS (defined in novas.h).
      accuracy (short int)
         Code specifying the relative accuracy of the output position.
            = 0 ... full accuracy
            = 1 ... reduced accuracy

   OUTPUT
   ARGUMENTS:
      *ra (double)
         Apparent right ascension in hours, referred to true equator
         and equinox of date 'jd_tt'.
      *dec (double)
         Apparent declination in degrees, referred to true equator
         and equinox of date 'jd_tt'.

   RETURNED
   VALUE:
      (short int)
          =  0 ... Everything OK.
          > 10 ... Error code from function 'MakeObject'.
          > 20 ... Error code from function 'place'.

   GLOBALS
   USED:
      SIZE_OF_OBJ_NAME   novas.h

   FUNCTIONS
   CALLED:
      MakeObject        novas.c
      place              novas.c
      strcpy             string.h

   VER./DATE/
   PROGRAMMER:
      V1.0/12-05/JAB (USNO/AA)
      V1.1/10-06/JAB (USNO/AA): Incorporate 'output' structure.
      V1.2/10-08/JAB (USNO/AA): Add 'accuracy' option to input.
      V1.3/05-10/JAB (USNO/AA): Fix bug in set-up of 'obj_name'.

   NOTES:
      1. This function is the "C" version of Fortran NOVAS routine
      'apstar'.
      2. SIZE_OF_OBJ_NAME is defined in novas.h

------------------------------------------------------------------------
*/

func AppStar(jd_tt float64, star CatEntry, accuracy int16, ra, dec *float64) int16 {
	/*
	   short int app_star (double jd_tt, CatEntry *star, short int accuracy,
	                       double *ra, double *dec) {
	*/

	/*
	   char obj_name[SIZE_OF_OBJ_NAME]

	   short int error = 0
	   short int type, number, coord_sys

	   double delta_t = 0.0

	   object cel_obj

	   observer location

	   SkyPos output
	*/
	var error int16
	var objType int16
	var number int16
	var coord_sys int16
	var cel_obj Object
	var location Observer
	var output SkyPos
	delta_t := float64(0.0)

	// Set 'obj_name' equal to 'starname' in the 'star' structure.  Length
	// will be checked in 'MakeObject'.

	//strcpy (obj_name, star->starname)
	obj_name := star.Starname

	// Set up a structure of type 'object' containing the star data.

	objType = 2 // Object located outside the solar system
	number = 0  // Set to zero

	if error = MakeObject(objType, number, obj_name, &star, &cel_obj); error != 0 {
		error += 10
		return error
	}

	// Compute the apparent place with a call to function 'place'.
	location.Where = 0 // Geocenter
	coord_sys = 1      // True equator and equinox of date

	if error = place(jd_tt, &cel_obj, &location, delta_t, coord_sys,
		accuracy, &output); error != 0 {
		*ra = float64(0.0)
		*dec = float64(0.0)
		error += 20
	} else {
		*ra = output.Ra
		*dec = output.Dec
	}

	return error
}

// ********virtual_star

/*
------------------------------------------------------------------------

   PURPOSE:
      Computes the virtual place of a star at date 'jd_tt', given its
      catalog mean place, proper motion, parallax, and radial velocity.

   REFERENCES:
      Kaplan, G. H. et. al. (1989). Astron. Journ. 97, 1197-1210.
      Explanatory Supplement to the Astronomical Almanac (1992),
         Chapter 3.

   INPUT
   ARGUMENTS:
      jd_tt (double)
         TT Julian date for virtual place.
      *star (struct CatEntry)
         Pointer to catalog entry structure containing catalog data for
         the object in the ICRS (defined in novas.h).
      accuracy (short int)
         Code specifying the relative accuracy of the output position.
            = 0 ... full accuracy
            = 1 ... reduced accuracy

   OUTPUT
   ARGUMENTS:
      *ra (double)
         Virtual right ascension in hours, referred to the GCRS.
      *dec (double)
         Virtual declination in degrees, referred to the GCRS.

   RETURNED
   VALUE:
      (short int)
          =  0 ... Everything OK.
          > 10 ... Error code from function 'MakeObject'.
          > 20 ... Error code from function 'place'.

   GLOBALS
   USED:
      SIZE_OF_OBJ_NAME   novas.h


   FUNCTIONS
   CALLED:
      MakeObject        novas.c
      place              novas.c
      strcpy             string.h

   VER./DATE/
   PROGRAMMER:
      V1.0/12-05/JAB (USNO/AA)
      V1.1/10-06/JAB (USNO/AA): Incorporate 'output' structure.
      V1.2/10-08/JAB (USNO/AA): Add 'accuracy' option to input.
      V1.3/05-10/JAB (USNO/AA): Fix bug in set-up of 'obj_name'.

   NOTES:
      1. This function is the "C" version of Fortran NOVAS routine
      'vpstar'.
      2. SIZE_OF_OBJ_NAME is defined in novas.h

------------------------------------------------------------------------
*/
/*
short int virtual_star (double jd_tt, CatEntry *star,
                        short int accuracy,
                        double *ra, double *dec)
*/

func virtual_star(jd_tt float64, star *CatEntry, accuracy int16,
	ra, dec *float64) int16 {
	/*
	   char obj_name[SIZE_OF_OBJ_NAME]

	   short int error = 0
	   short int objType, number, coord_sys

	   double delta_t = 0.0
	*/
	delta_t := float64(0.0)
	error := int16(0)

	var cel_obj Object

	var location Observer

	var output SkyPos

	// Set 'obj_name' equal to 'starname' in the 'star' structure.  Length
	// will be checked in 'MakeObject'.
	obj_name := star.Starname

	// Set up a structure of objType 'object' containing the star data.
	objType := int16(2) // Object located outside the solar system
	number := int16(0)  // Set to zero

	if error = MakeObject(objType, number, obj_name, star, &cel_obj); error != 0 {
		error += 10
		return (error)
	}

	// Compute the virtual place with a call to function 'place'.

	location.Where = 0    // Geocenter
	coord_sys := int16(0) // GCRS

	if error = place(jd_tt, &cel_obj, &location, delta_t, coord_sys,
		accuracy, &output); error != 0 {
		*ra = float64(0.0)
		*dec = float64(0.0)
		error += 20
	} else {
		*ra = output.Ra
		*dec = output.Dec
	}

	return error
}

// ********astro_star

/*
------------------------------------------------------------------------

   PURPOSE:
      Computes the astrometric place of a star at date 'jd_tt', given
      its catalog mean place, proper motion, parallax, and radial
      velocity.

   REFERENCES:
      Kaplan, G. H. et. al. (1989). Astron. Journ. 97, 1197-1210.
      Explanatory Supplement to the Astronomical Almanac (1992),
         Chapter 3.

   INPUT
   ARGUMENTS:
      jd_tt (double)
         TT Julian date for astrometric place.
      *star (struct CatEntry)
         Pointer to catalog entry structure containing catalog data for
         the object in the ICRS (defined in novas.h).
      accuracy (short int)
         Code specifying the relative accuracy of the output position.
            = 0 ... full accuracy
            = 1 ... reduced accuracy

   OUTPUT
   ARGUMENTS:
      *ra (double)
         Astrometric right ascension in hours (referred to the ICRS,
         without light deflection or aberration).
      *dec (double)
         Astrometric declination in degrees (referred to the ICRS,
         without light deflection or aberration).

   RETURNED
   VALUE:
      (short int)
          =  0 ... Everything OK.
          > 10 ... Error code from function 'MakeObject'.
          > 20 ... Error code from function 'place'.

   GLOBALS
   USED:
      SIZE_OF_OBJ_NAME   novas.h

   FUNCTIONS
   CALLED:
      MakeObject        novas.c
      place              novas.c
      strcpy             string.h

   VER./DATE/
   PROGRAMMER:
      V1.0/12-05/JAB (USNO/AA)
      V1.1/10-06/JAB (USNO/AA): Incorporate 'output' structure.
      V1.2/10-08/JAB (USNO/AA): Add 'accuracy' option to input.
      V1.3/05-10/JAB (USNO/AA): Fix bug in set-up of 'obj_name'.

   NOTES:
      1. This function is the "C" version of Fortran NOVAS routine
      'asstar'.
      2. SIZE_OF_OBJ_NAME is defined in novas.h

------------------------------------------------------------------------
*/
/*
short int astro_star (double jd_tt, CatEntry *star, short int accuracy,
                      double *ra, double *dec)
*/
func astro_star(jd_tt float64, star *CatEntry, accuracy int16,
	ra, dec *float64) int16 {

	/*
	   char obj_name[SIZE_OF_OBJ_NAME]

	   short int error = 0
	   short int objType, number, coord_sys
	*/
	error := int16(0)
	delta_t := float64(0.0)

	var cel_obj Object

	var location Observer

	var output SkyPos

	// Set 'obj_name' equal to 'starname' in the 'star' structure.  Length
	// will be checked in 'MakeObject'.
	// strcpy (obj_name, star->starname)
	obj_name := star.Starname

	// Set up a structure of type 'object' containing the star data.
	objType := int16(2) // Object located outside the solar system
	number := int16(0)  // Set to zero

	if error = MakeObject(objType, number, obj_name, star, &cel_obj); error != 0 {
		error += 10
		return (error)
	}

	// Compute the astrometric place with a call to function 'place'.
	location.Where = 0    // Geocenter
	coord_sys := int16(3) // ICRS astrometric coordinates

	if error = place(jd_tt, &cel_obj, &location, delta_t, coord_sys,
		accuracy, &output); error != 0 {
		*ra = float64(0.0)
		*dec = float64(0.0)
		error += 20
	} else {
		*ra = output.Ra
		*dec = output.Dec
	}

	return error
}

// *******app_planet */
/*
------------------------------------------------------------------------

   PURPOSE:
      Compute the apparent place of a solar system body.

   REFERENCES:
      Kaplan, G. H. et. al. (1989). Astron. Journ. 97, 1197-1210.
      Explanatory Supplement to the Astronomical Almanac (1992),
         Chapter 3.

   INPUT
   ARGUMENTS:
      jd_tt (double)
         TT Julian date for apparent place.
      *ss_body (struct object)
         Pointer to structure containing the body designation for the
         solar system body (defined in novas.h).
      accuracy (short int)
         Code specifying the relative accuracy of the output position.
            = 0 ... full accuracy
            = 1 ... reduced accuracy

   OUTPUT
   ARGUMENTS:
      *ra (double)
         Apparent right ascension in hours, referred to true equator
         and equinox of date.
      *dec (double)
         Apparent declination in degrees, referred to true equator
         and equinox of date.
      *dis (double)
         True distance from Earth to the body at 'jd_tt' in AU.

   RETURNED
   VALUE:
      (short int)
          =  0 ... Everything OK.
          =  1 ... Invalid value of 'objType' in structure 'ss_body'.
          > 10 ... Error code from function 'place'.

   GLOBALS
   USED:
      None.

   FUNCTIONS
   CALLED:
      place              novas.c

   VER./DATE/
   PROGRAMMER:
      V1.0/12-05/JAB (USNO/AA)
      V1.1/10-06/JAB (USNO/AA): Incorporate 'output' structure.
      V1.2/10-08/JAB (USNO/AA): Add 'accuracy' option to input.

   NOTES:
      1. This function is the "C" version of Fortran NOVAS routine
      'applan'.

------------------------------------------------------------------------
*/
/*
short int app_planet (double jd_tt, object *ss_body, short int accuracy,
                      double *ra, double *dec, double *dis) {
*/
func app_planet(jd_tt float64, ss_body *Object, accuracy int16,
	ra, dec, dis *float64) int16 {
	/*
	   short int error = 0
	   short int coord_sys
	*/
	error := int16(0)

	delta_t := float64(0.0)

	var location Observer

	var output SkyPos

	// Check for a valid value of 'type' in structure 'ss_body'.
	if (ss_body.Type < 0) || (ss_body.Type > 1) {
		error = 1
		return error
	}

	// Compute the apparent place with a call to function 'place'.
	location.Where = 0    // Geocenter
	coord_sys := int16(1) // True equator and equinox of date

	if error = place(jd_tt, ss_body, &location, delta_t, coord_sys,
		accuracy, &output); error != 0 {
		*ra = float64(0.0)
		*dec = float64(0.0)
		*dis = float64(0.0)
		error += 10
	} else {
		*ra = output.Ra
		*dec = output.Dec
		*dis = output.Dis
	}

	return (error)
}

