// ********topo_star

/*
------------------------------------------------------------------------

   PURPOSE:
      Computes the topocentric place of a star at date 'jd_tt', given its
      catalog mean place, proper motion, parallax, and radial velocity.

   REFERENCES:
      Kaplan, G. H. et. al. (1989). Astron. Journ. 97, 1197-1210.
      Explanatory Supplement to the Astronomical Almanac (1992),
         Chapter 3.

   INPUT
   ARGUMENTS:
      jd_tt (double)
         TT Julian date for topocentric place.
      delta_t (double)
         Difference TT-UT1 at 'jd_tt', in seconds of time.
      *star (struct CatEntry)
         Pointer to catalog entry structure containing catalog data for
         the object in the ICRS (defined in novas.h).
      *position (struct OnSurface)
         Specifies the position of the observer (structure defined in
         novas.h).
      accuracy (short int)
         Code specifying the relative accuracy of the output position.
            = 0 ... full accuracy
            = 1 ... reduced accuracy

   OUTPUT
   ARGUMENTS:
      *ra (double)
         Topocentric right ascension in hours, referred to true equator
         and equinox of date 'jd_tt'.
      *dec (double)
         Topocentric declination in degrees, referred to true equator
         and equinox of date 'jd_tt'.

   RETURNED
   VALUE:
      (short int)
           =  0 ... Everything OK.
           =  1 ... Invalid value of 'where' in structure 'location'.
           > 10 ... Error code from function 'MakeObject'.
           > 20 ... Error code from function 'place'.

   GLOBALS
   USED:
      SIZE_OF_OBJ_NAME   novas.h

   FUNCTIONS
   CALLED:
      make_observer      novas.c
      MakeObject        novas.c
      place              novas.c
      strcpy             string.h

   VER./DATE/
   PROGRAMMER:
      V1.0/01-06/JAB (USNO/AA)
      V1.1/01-06/WKP (USNO/AA): Fixed minor syntax problem.
      V1.2/10-06/JAB (USNO/AA): Incorporate 'output' structure.
      V1.3/10-08/JAB (USNO/AA): Add 'accuracy' option to input.
      V1.4/05-10/JAB (USNO/AA): Fix bug in set-up of 'obj_name'.

   NOTES:
      1. This function is the "C" version of Fortran NOVAS routine
      'tpstar'.
      2. SIZE_OF_OBJ_NAME is defined in novas.h

------------------------------------------------------------------------
*/
/*
short int topo_star (double jd_tt, double delta_t, CatEntry *star,
                     OnSurface *position, short int accuracy,
                     double *ra, double *dec)
*/
func TopoStar(jd_tt, delta_t float64, star *CatEntry, position *OnSurface,
	accuracy int16, ra, dec *float64) error {
	/*
		fmt.Println("Calling TopoStar with: ")
		fmt.Println("   jd_tt: ", jd_tt)
		fmt.Println("   delta_t: ", delta_t)
		fmt.Println("   star: ", star)
		fmt.Println("   postion: ", position)
		fmt.Println("   accuracy: ", accuracy)
	*/

	//char obj_name[SIZE_OF_OBJ_NAME]

	//short int error = 0
	error := int16(0)

	//short int objType, number, coord_sys

	//InSpace dummy
	var dummy InSpace

	//observer location
	var location Observer

	//object cel_obj
	var cel_obj Object

	//SkyPos output
	var output SkyPos

	// Initialize the 'dummy' structure.
	dummy.Sc_pos[0] = float64(0.0)
	//dummy.Sc_pos[0] = dummy.Sc_pos[1] = dummy.Sc_pos[2] = 0.0
	//dummy.Sc_vel[0] = dummy.Sc_vel[1] = dummy.Sc_vel[2] = 0.0

	// Set up a structure of type 'observer' containing the position
	// of the observer.

	if error = make_observer(1, position, &dummy, &location); error != 0 {
		error = 1
		emsg := fmt.Sprintf("NOVAS Error Code: %d", error)
		return errors.New(emsg)
	}
	//fmt.Println("TopoStar: location: ", location)
	// Set 'obj_name' equal to 'starname' in the 'star' structure.  Length
	// will be checked in 'MakeObject'.

	//strcpy (obj_name, star->starname)
	obj_name := star.Starname
	//fmt.Println("TopoStar: obj_name: ", obj_name)
	// Set up a structure of type 'object' containing the star data.

	objType := int16(2) // Object located outside the solar system
	number := int16(0)  // Set to zero

	if error = MakeObject(objType, number, obj_name, star, &cel_obj); error != 0 {
		error += 10
		emsg := fmt.Sprintf("NOVAS TopoStar in MakeObject. Error Code: %d", error)
		return errors.New(emsg)
	}
	//fmt.Println("TopoStar: cel_obj: ", cel_obj)
	// Compute the topocentric place with a call to function 'place'.
	coord_sys := int16(1) // True equator and equinox of date

	if error = place(jd_tt, &cel_obj, &location, delta_t, coord_sys,
		accuracy, &output); error != 0 {
		*ra = float64(0.0)
		*dec = float64(0.0)
		error += 20
		fmt.Println("TopoStar: error in place. error: ", error)
	} else {
		//fmt.Println("TopoStar: output.Ra: ", output.Ra)
		//fmt.Println("TopoStar: output.Dec: ", output.Dec)
		*ra = output.Ra
		*dec = output.Dec
	}

	return nil
}

// ********local_star
/*
short int local_star (double jd_tt, double delta_t, CatEntry *star,
                      OnSurface *position, short int accuracy,
                      double *ra, double *dec)
*/
/*
------------------------------------------------------------------------

   PURPOSE:
      Computes the local place of a star at date 'jd_tt', given its
      catalog mean place, proper motion, parallax, and radial velocity.

   REFERENCES:
      Kaplan, G. H. et. al. (1989). Astron. Journ. 97, 1197-1210.
      Explanatory Supplement to the Astronomical Almanac (1992),
         Chapter 3.

   INPUT
   ARGUMENTS:
      jd_tt (double)
         TT Julian date for local place.
      delta_t (double)
         Difference TT-UT1 at 'jd_tt', in seconds of time.
      *star (struct CatEntry)
         Pointer to catalog entry structure containing catalog data for
         the object in the ICRS (defined in novas.h).
      *position (struct OnSurface)
         Specifies the position of the observer (structure defined in
         novas.h).
      accuracy (short int)
         Code specifying the relative accuracy of the output position.
            = 0 ... full accuracy
            = 1 ... reduced accuracy

   OUTPUT
   ARGUMENTS:
      *ra (double)
         Local right ascension in hours, referred to the 'local GCRS'.
      *dec (double)
         Local declination in degrees, referred to the 'local GCRS'.

   RETURNED
   VALUE:
      (short int)
           =  0 ... Everything OK.
           =  1 ... Invalid value of 'where' in structure 'location'.
           > 10 ... Error code from function 'MakeObject'.
           > 20 ... Error code from function 'place'.

   GLOBALS
   USED:
      SIZE_OF_OBJ_NAME   novas.h

   FUNCTIONS
   CALLED:
      make_observer      novas.c
      MakeObject        novas.c
      place              novas.c
      strcpy             string.h

   VER./DATE/
   PROGRAMMER:
      V1.0/01-06/JAB (USNO/AA)
      V1.1/10-06/JAB (USNO/AA): Incorporate 'output' structure.
      V1.2/10-08/JAB (USNO/AA): Add 'accuracy' option to input.
      V1.3/05-10/JAB (USNO/AA): Fix bug in set-up of 'obj_name'.

   NOTES:
      1. This function is the "C" version of Fortran NOVAS routine
      'lpstar'.
      2. SIZE_OF_OBJ_NAME is defined in novas.h

------------------------------------------------------------------------
*/
/*
{
   char obj_name[SIZE_OF_OBJ_NAME]

   short int error = 0
   short int objType, number, coord_sys

   InSpace dummy

   observer location

   object cel_obj

   SkyPos output


   // Initialize the 'dummy' structure.
   dummy.sc_pos[0] = dummy.sc_pos[1] = dummy.sc_pos[2] = 0.0
   dummy.sc_vel[0] = dummy.sc_vel[1] = dummy.sc_vel[2] = 0.0


   // Set up a structure of type 'observer' containing the position
   // of the observer.
   if ((error = make_observer (1,position,&dummy, &location)) != 0)
   {
      error = 1
      return (error)
   }


   // Set 'obj_name' equal to 'starname' in the 'star' structure.  Length
   // will be checked in 'MakeObject'.
   strcpy (obj_name, star->starname)


   // Set up a structure of objType 'object' containing the star data.

   objType = 2   // Object located outside the solar system
   number = 0    // Set to zero

   if ((error = MakeObject (objType,number,obj_name,star, &cel_obj)) != 0)
   {
      error += 10
      return (error)
   }


   // Compute the local place with a call to function 'place'.
   coord_sys = 0        // "Local GCRS"

   if ((error = place (jd_tt,&cel_obj,&location,delta_t,coord_sys,
      accuracy, &output)) != 0)
   {
      *ra = 0.0
      *dec = 0.0
      error += 20
   }
    else
   {
      *ra = output.Ra
      *dec = output.Dec
   }

   return (error)
}
*/

// ********TopoPlanet
/*
short int TopoPlanet (double jd_tt, object *ss_body, double delta_t,
                       OnSurface *position, short int accuracy,
                       double *ra, double *dec, double *dis)
*/
/*
------------------------------------------------------------------------

   PURPOSE:
      Computes the topocentric place of a solar system body.

   REFERENCES:
      Kaplan, G. H. et. al. (1989). Astron. Journ. 97, 1197-1210.
      Explanatory Supplement to the Astronomical Almanac (1992),
         Chapter 3.

   INPUT
   ARGUMENTS:
      jd_tt (double)
         TT Julian date for topocentric place.
      *ss_body (struct object)
         Pointer to structure containing the body designation for the
         solar system body (defined in novas.h).
      delta_t (double)
         Difference TT-UT1 at 'jd_tt', in seconds of time.
      *position (struct OnSurface)
         Specifies the position of the observer (structure defined in
         novas.h).
      accuracy (short int)
         Code specifying the relative accuracy of the output position.
            = 0 ... full accuracy
            = 1 ... reduced accuracy

   OUTPUT
   ARGUMENTS:
      *ra (double)
         Topocentric right ascension in hours, referred to true equator
         and equinox of date.
      *dec (double)
         Topocentric declination in degrees, referred to true equator
         and equinox of date.
      *dis (double)
         True distance from Earth to the body at 'jd_tt' in AU.

   RETURNED
   VALUE:
      (short int)
           =  0 ... Everything OK.
           =  1 ... Invalid value of 'where' in structure 'location'.
           > 10 ... Error code from function 'place'.

   GLOBALS
   USED:
      None.

   FUNCTIONS
   CALLED:
      make_observer      novas.c
      place              novas.c

   VER./DATE/
   PROGRAMMER:
      V1.0/01-06/JAB (USNO/AA)
      V1.1/01-06/WKP (USNO/AA): Fixed minor syntax problem.
      V1.2/10-06/JAB (USNO/AA): Incorporate 'output' structure.
      V1.3/10-08/JAB (USNO/AA): Add 'accuracy' option to input.
      V1.4/07-10/JLB (USNO/AA): Fixed minor documentation error in prolog

   NOTES:
      1. This function is the "C" version of Fortran NOVAS routine
      'tpplan'.

------------------------------------------------------------------------
*/
/*
{
   short int error = 0
   short int coord_sys

   InSpace dummy

   observer location

   SkyPos output


   // Initialize the 'dummy' structure.

   dummy.sc_pos[0] = dummy.sc_pos[1] = dummy.sc_pos[2] = 0.0
   dummy.sc_vel[0] = dummy.sc_vel[1] = dummy.sc_vel[2] = 0.0


   // Set up a structure of type 'observer' containing the position
   // of the observer.
   if ((error = make_observer (1,position,&dummy, &location)) != 0)
   {
      error = 1
      return (error)
   }


   // Compute the topocentric place with a call to function 'place'.
   coord_sys = 1        // True equator and equinox of date

   if ((error = place (jd_tt,ss_body,&location,delta_t,coord_sys,
      accuracy, &output)) != 0)
   {
      *ra = 0.0
      *dec = 0.0
      *dis = 0.0
      error += 10
   }
    else
   {
      *ra = output.Ra
      *dec = output.Dec
      *dis = output.Dis
   }

   return (error)
   }
*/
func TopoPlanet(jd_tt float64, ss_body *Object, delta_t float64,
	position *OnSurface, accuracy int16,
	ra, dec, dis *float64) error {

	//short int error = 0
	//short int coord_sys
	error := 0
	var coord_sys int16

	//InSpace dummy
	var dummy InSpace

	//observer location
	var location Observer

	// SkyPos output
	var output SkyPos

	// Initialize the 'dummy' structure.

	dummy.Sc_pos[0] = 0.0
	dummy.Sc_pos[1] = 0.0
	dummy.Sc_pos[2] = 0.0
	dummy.Sc_vel[0] = 0.0
	dummy.Sc_vel[1] = 0.0
	dummy.Sc_vel[2] = 0.0

	// Set up a structure of type 'observer' containing the position
	// of the observer.
	if errorVal := make_observer(1, position, &dummy, &location); errorVal != 0 {
		error := 1
		emsg := fmt.Sprintf("errorVal= %d", error)
		return errors.New(emsg)
	}

	// Compute the topocentric place with a call to function 'place'.
	coord_sys = 1 // True equator and equinox of date

	if error := place(jd_tt, ss_body, &location, delta_t, coord_sys,
		accuracy, &output); error != 0 {

		*ra = 0.0
		*dec = 0.0
		*dis = 0.0
		error += 10
	} else {
		*ra = output.Ra
		*dec = output.Dec
		*dis = output.Dis
	}

	if error != 0 {
		emsg := fmt.Sprintf("errorVal= %d", error)
		return errors.New(emsg)
	} else {
		return nil
	}
}

